;   B = $7F  bank 1, all RAM                    (variables, strings, arrays)                              [sure, VICE]
;   C = $01  bank 0, all ROMs (BASIC/KERNAL), no I/O   (used by rom_call and the $0300 vector)            [sure, VICE]
